select budget_bucket, min_budget, pct_engineering from (select case when budget >= 3893000 then 'high' when budget >= 1892000 then 'mid' else 'low' end budget_bucket, min(budget) min_budget, round((100 * sum(case when dept_name = 'Engineering' then 1 else 0 end)) / count(*), 1) pct_engineering from departments group by case when budget >= 3893000 then 'high' when budget >= 1892000 then 'mid' else 'low' end) s where pct_engineering > 69
